INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-ics321', 'stk-mohammed_mag', 'ICS 321', 'doc', '{"docs": [{"id": "stk-dr-f98297", "n": "Dr. Jaweed Yazdeni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 321 - Database\n\nالتحضير : يحضر اخر الكلاس بالاسامي، بعض الاحيان مايحضر مثلا اذا خذا وقت زياده اخر الكلاس.\n\nطريقة الشرح : يشرح سلايدات الكورس، وشرحه جميل غالبا يسولف عن تجاربة ويتكلم عن الواقع وواضح معاه خبره طويله في هذا الشيء .\n\nالكويزات : متوسطه الصعوبة، لكن طويله اغلب الكويزات ورقتين، 5 كويزات خذ افضل 4 .\n\nالصوت : واضح و أكسنت مفهوم .\n\nإضافات :\nالدكتور جدا محترم ويعيد النقطه اكثر من مره لين ماتثبت، متساهل نوعا بالتحضير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536729-ics321", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-jaweed-yazdeni/98297/4", "user": "Mohammed_Mag", "ts": 1685666717000, "tid": 98297, "pn": 4}}]}', 1685666717000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
